def test_forward_over_weekend_and_holidays():
    assert add_business_days('2026-10-30', 1, []) == '2026-11-02'
    assert add_business_days('2026-10-30', 10, ['2026-11-11', '2026-11-26']) == '2026-11-16'


def test_start_never_counted():
    assert add_business_days('2026-11-02', 1, []) == '2026-11-03'
    assert add_business_days('2026-10-31', 1, []) == '2026-11-02'
    assert add_business_days('2026-10-17', 1, []) == '2026-10-19'


def test_backward():
    assert add_business_days('2026-11-02', -1, []) == '2026-10-30'
    assert add_business_days('2026-11-01', -1, []) == '2026-10-30'
    assert add_business_days('2026-11-02', -1, ['2026-10-30']) == '2026-10-29'


def test_observed_saturday_holiday():
    assert add_business_days('2026-07-02', 1, ['2026-07-04']) == '2026-07-06'
    assert add_business_days('2021-12-30', 1, ['2022-01-01']) == '2022-01-03'


def test_observed_sunday_holiday():
    assert add_business_days('2027-07-02', 1, ['2027-07-04']) == '2027-07-06'
    assert add_business_days('2026-11-03', -3, ['2026-11-01', '2026-10-30']) == '2026-10-27'


def test_zero_on_business_day_unchanged():
    assert add_business_days('2026-10-29', 0, []) == '2026-10-29'


def test_zero_rolls_forward_within_month():
    assert add_business_days('2026-10-17', 0, []) == '2026-10-19'
    assert add_business_days('2026-07-03', 0, ['2026-07-04']) == '2026-07-06'
    assert add_business_days('2026-02-01', 0, ['2026-02-01']) == '2026-02-03'
    assert add_business_days('2026-11-11', 0, ['2026-11-11']) == '2026-11-12'


def test_zero_modified_following_rolls_back_at_month_end():
    assert add_business_days('2026-01-31', 0, []) == '2026-01-30'
    assert add_business_days('2026-01-31', 0, ['2026-01-30']) == '2026-01-29'
    assert add_business_days('2026-12-31', 0, ['2026-12-31']) == '2026-12-30'


def test_zero_modified_following_with_observed_holiday():
    assert add_business_days('2026-10-31', 0, ['2026-10-31']) == '2026-10-29'

