from datetime import date, timedelta


def add_business_days(start: str, n: int, holidays: list) -> str:
    closed = set()
    for h in holidays:
        d = date.fromisoformat(h)
        closed.add(d)
        if d.weekday() == 5:
            closed.add(d - timedelta(days=1))
        elif d.weekday() == 6:
            closed.add(d + timedelta(days=1))

    def is_bd(x):
        return x.weekday() < 5 and x not in closed

    d = date.fromisoformat(start)
    if n == 0:
        if is_bd(d):
            return d.isoformat()
        f = d + timedelta(days=1)
        while not is_bd(f):
            f += timedelta(days=1)
        if f.month == d.month:
            return f.isoformat()
        b = d - timedelta(days=1)
        while not is_bd(b):
            b -= timedelta(days=1)
        return b.isoformat()
    step = 1 if n > 0 else -1
    count = 0
    while count < abs(n):
        d += timedelta(days=step)
        if is_bd(d):
            count += 1
    return d.isoformat()

