def test_equal_weights_lower_index_first():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_largest_remainder():
    assert allocate(10, [1, 2]) == [3, 7]
    assert allocate(1000, [3, 0, 7, 5]) == [200, 0, 467, 333]
    assert allocate(3, [1, 4]) == [1, 2]


def test_tie_goes_to_larger_weight():
    assert allocate(6, [1, 3]) == [1, 5]
    assert allocate(2, [1, 3]) == [0, 2]


def test_zero_weight_and_zero_total():
    assert allocate(5, [0, 1, 1]) == [0, 3, 2]
    assert allocate(0, [1, 2]) == [0, 0]


def test_negative_totals_mirror_positive():
    assert allocate(-10, [1, 2]) == [-3, -7]
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]
    assert allocate(-6, [1, 3]) == [-1, -5]


def test_all_zero_weights_split_evenly():
    assert allocate(7, [0, 0, 0]) == [3, 2, 2]
    assert allocate(-7, [0, 0]) == [-4, -3]


def test_shares_always_sum_to_total():
    for total in (-1001, -17, 1, 99, 12345):
        for weights in ([1], [2, 3], [5, 0, 5, 1], [7, 7, 7, 7, 7, 7]):
            out = allocate(total, weights)
            assert sum(out) == total
            assert all(isinstance(x, int) for x in out)

