from decimal import Decimal, ROUND_HALF_EVEN

_BRACKETS = [
    (Decimal("0"), Decimal("1000"), Decimal("0.029")),
    (Decimal("1000"), Decimal("10000"), Decimal("0.025")),
    (Decimal("10000"), None, Decimal("0.015")),
]


def platform_fee(amount: str) -> str:
    a = Decimal(amount)
    cent = Decimal("0.01")
    if a == 0:
        return "0.00"
    fee = Decimal("0.30")
    for lo, hi, rate in _BRACKETS:
        if a <= lo:
            break
        top = a if hi is None else min(a, hi)
        fee += ((top - lo) * rate).quantize(cent, rounding=ROUND_HALF_EVEN)
    fee = max(fee, Decimal("0.50"))
    fee = min(fee, Decimal("500.00"))
    return str(fee.quantize(cent))

