def platform_fee(amount: str) -> str:
    a = float(amount)
    if a == 0:
        return "0.00"
    fee = 0.30
    for lo, hi, rate in ((0.0, 1000.0, 0.029), (1000.0, 10000.0, 0.025), (10000.0, None, 0.015)):
        if a <= lo:
            break
        top = a if hi is None else min(a, hi)
        fee += float(Decimal(repr((top - lo) * rate)).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN))
    fee = max(fee, 0.50)
    fee = min(fee, 500.00)
    return f"{fee:.2f}"

