import pytest


def test_basic_components():
    assert normalize_duration('2h45m') == '2:45:00'
    assert normalize_duration('90m') == '1:30:00'
    assert normalize_duration('1d 30s') == '24:00:30'


def test_case_order_and_repeats():
    assert normalize_duration('1H 1h 30S') == '2:00:30'
    assert normalize_duration('45s3d') == '72:00:45'


@pytest.mark.parametrize('bad', ['', '   ', '10', '5x', '5 h', 'h5', '1h 2'])
def test_invalid_inputs(bad):
    with pytest.raises(ValueError):
        normalize_duration(bad)


def test_decimal_values_exact():
    assert normalize_duration('1.5h') == '1:30:00'
    assert normalize_duration('0.25m') == '0:00:15'
    assert normalize_duration('0.14125h') == '0:08:29'


def test_halves_round_up():
    assert normalize_duration('2.5s') == '0:00:03'
    assert normalize_duration('0.5s') == '0:00:01'
    assert normalize_duration('1d 1.5h 0.5s') == '25:30:01'


@pytest.mark.parametrize('bad', ['1.h', '.5h', '1.2.3h'])
def test_invalid_decimal_forms(bad):
    with pytest.raises(ValueError):
        normalize_duration(bad)


def test_negative_durations():
    assert normalize_duration('-1h30m') == '-1:30:00'
    assert normalize_duration('-1d') == '-24:00:00'
    assert normalize_duration('-0.5s') == '-0:00:01'
    assert normalize_duration('-2.5s') == '-0:00:03'


def test_negative_rounding_to_zero_has_no_sign():
    assert normalize_duration('-0.4s') == '0:00:00'


@pytest.mark.parametrize('bad', ['-', '1h-30m', '--1h'])
def test_invalid_signs(bad):
    with pytest.raises(ValueError):
        normalize_duration(bad)

