from decimal import Decimal, ROUND_HALF_EVEN

_ONES = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
         "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
_TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]


def _below_100(n):
    if n < 20:
        return _ONES[n]
    t, u = divmod(n, 10)
    return _TENS[t] + ("-" + _ONES[u] if u else "")


def _group(n):
    h, r = divmod(n, 100)
    parts = []
    if h:
        parts.append(_ONES[h] + " hundred")
        if r:
            parts.append("and")
    if r:
        parts.append(_below_100(r))
    return " ".join(parts)


def cheque_words(amount: str) -> str:
    q = Decimal(amount).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
    whole = int(q)
    cents = int((q - whole) * 100)
    if whole == 0:
        words = "zero"
    else:
        millions, rest = divmod(whole, 1000000)
        thousands, units = divmod(rest, 1000)
        parts = []
        if millions:
            parts.append(_group(millions) + " million")
        if thousands:
            parts.append(_group(thousands) + " thousand")
        if units:
            if (millions or thousands) and units < 100:
                parts.append("and")
            parts.append(_group(units))
        words = " ".join(parts)
    unit = "dollar" if whole == 1 else "dollars"
    text = f"{words} {unit} and {cents:02d}/100"
    return text[0].upper() + text[1:]

