import calendar
from datetime import date
from decimal import Decimal
from fractions import Fraction


def _last_of_feb(d):
    return d.month == 2 and d.day == calendar.monthrange(d.year, 2)[1]


def accrued_interest(principal: str, annual_rate: str, start: str, end: str, convention: str) -> str:
    s = date.fromisoformat(start)
    e = date.fromisoformat(end)
    if convention == "ACT/365":
        yf = Fraction((e - s).days, 365)
    elif convention == "ACT/360":
        yf = Fraction((e - s).days, 360)
    elif convention == "30/360":
        d1, d2 = s.day, e.day
        if _last_of_feb(s) and _last_of_feb(e):
            d2 = 30
        if _last_of_feb(s):
            d1 = 30
        if d1 == 31:
            d1 = 30
        if d2 == 31 and d1 == 30:
            d2 = 30
        days = 360 * (e.year - s.year) + 30 * (e.month - s.month) + (d2 - d1)
        yf = Fraction(days, 360)
    elif convention == "ACT/ACT":
        yf = Fraction(0)
        cur = s
        while cur < e:
            nxt = min(e, date(cur.year + 1, 1, 1))
            yf += Fraction((nxt - cur).days, 366 if calendar.isleap(cur.year) else 365)
            cur = nxt
    else:
        raise ValueError(f"unknown convention: {convention!r}")
    x = Fraction(Decimal(principal)) * Fraction(Decimal(annual_rate)) * yf * 100
    cents = (2 * x.numerator + x.denominator) // (2 * x.denominator)
    return f"{cents // 100}.{cents % 100:02d}"

