import calendar
from datetime import date


def tenure(start: str, end: str) -> str:
    s = date.fromisoformat(start)
    e = date.fromisoformat(end)

    def plus(k):
        m0 = s.month - 1 + k
        y, m = s.year + m0 // 12, m0 % 12 + 1
        last = calendar.monthrange(y, m)[1]
        if s.month == 2 and s.day == 29 and m == 2 and last == 28:
            return date(y, 3, 1)
        return date(y, m, min(s.day, last))

    k = 0
    while plus(k + 1) <= e:
        k += 1
    return f"{k // 12}y {k % 12}m {(e - plus(k)).days}d"

