import calendar
from datetime import date


def tenure(start: str, end: str) -> str:
    s = date.fromisoformat(start)
    e = date.fromisoformat(end)
    years = e.year - s.year
    months = e.month - s.month
    days = e.day - s.day
    if days < 0:
        months -= 1
        py, pm = (e.year - 1, 12) if e.month == 1 else (e.year, e.month - 1)
        days += calendar.monthrange(py, pm)[1]
    if months < 0:
        years -= 1
        months += 12
    return f"{years}y {months}m {days}d"

