def _week(days, start, end):
    return [('2026-03-%02d' % d, start, end) for d in days]


def test_single_shift_with_daily_overtime():
    assert weekly_pay([('2026-03-02', '09:00', '17:30')], 2000) == 17500


def test_quarter_hour_rounding_boundary():
    assert weekly_pay([('2026-03-02', '09:00', '17:07')], 2000) == 16000
    assert weekly_pay([('2026-03-02', '09:00', '17:08')], 2000) == 16750


def test_each_shift_rounded_separately():
    shifts = [('2026-03-02', '08:00', '12:05'), ('2026-03-02', '13:00', '17:05')]
    assert weekly_pay(shifts, 2000) == 16000


def test_overnight_shift_counts_toward_its_date():
    assert weekly_pay([('2026-03-02', '22:00', '06:30')], 2000) == 17500


def test_final_rounding_half_up():
    assert weekly_pay([('2026-03-02', '09:00', '09:30')], 1001) == 501
    assert weekly_pay([('2026-03-02', '09:00', '17:15')], 1999) == 16742


def test_weekly_overtime_after_2400_regular_minutes():
    shifts = _week([2, 3, 4, 5, 6], '08:00', '17:00') + [('2026-03-07', '10:00', '14:00')]
    assert weekly_pay(shifts, 2000) == 107000
    assert weekly_pay(list(reversed(shifts)), 2000) == 107000
    shifts = _week([2, 3, 4, 5, 6], '09:00', '17:00') + [('2026-03-07', '09:00', '09:08')]
    assert weekly_pay(shifts, 1800) == 72675


def test_weekly_overtime_splits_a_day():
    shifts = [('2026-03-07', '08:00', '13:00'), ('2026-03-06', '08:00', '13:00')] + _week([2, 4, 3, 5], '08:00', '17:00')
    assert weekly_pay(shifts, 2000) == 98000


def test_double_time():
    assert weekly_pay([('2026-03-02', '06:00', '19:00')], 2000) == 32000
    assert weekly_pay([('2026-03-02', '18:00', '07:10')], 1500) == 24750


def test_double_time_with_weekly_overtime():
    shifts = [('2026-03-07', '09:00', '11:00'), ('2026-03-02', '06:00', '19:00')] + _week([3, 4, 5, 6], '08:00', '17:00')
    assert weekly_pay(shifts, 2000) == 114000

