def parse_money(text: str) -> int:
    s = text.strip()
    neg = False
    signs_allowed = True
    if len(s) >= 2 and s[0] == "(" and s[-1] == ")":
        s = s[1:-1]
        neg = True
        signs_allowed = False
    if s[:1] in ("+", "-") and s:
        if not signs_allowed:
            raise ValueError(text)
        neg = s[0] == "-"
        s = s[1:]
    if s.startswith("$"):
        s = s[1:]
    if not re.fullmatch(r"[0-9.,]+", s):
        raise ValueError(text)
    has_dot, has_comma = "." in s, "," in s
    if has_dot and has_comma:
        dec = "." if s.rfind(".") > s.rfind(",") else ","
        grp = "," if dec == "." else "."
        if s.count(dec) != 1:
            raise ValueError(text)
        int_part, frac = s.split(dec)
    elif has_dot or has_comma:
        sep = "." if has_dot else ","
        idx = s.index(sep)
        if s.count(sep) == 1 and len(s) - idx - 1 in (1, 2):
            int_part, frac, grp = s[:idx], s[idx + 1:], None
        else:
            int_part, frac, grp = s, None, sep
    else:
        int_part, frac, grp = s, None, None
    if grp is None:
        ok = re.fullmatch(r"\d+", int_part)
    else:
        ok = re.fullmatch(r"\d{1,3}(?:" + re.escape(grp) + r"\d{3})+", int_part)
    if not ok:
        raise ValueError(text)
    if frac is not None and not re.fullmatch(r"\d{1,2}", frac):
        raise ValueError(text)
    digits = int_part.replace(grp, "") if grp else int_part
    cents = int(digits) * 100 + (int(frac.ljust(2, "0")) if frac else 0)
    return -cents if neg else cents

