def _l(qty, price, taxable):
    return {'qty': qty, 'price': price, 'taxable': taxable}


def test_basic_invoice():
    out = invoice_total([_l(3, '19.99', True), _l(1, '5.00', False)], '0.0825')
    assert out == {'subtotal': '64.97', 'discount': '0.00', 'tax': '4.95', 'total': '69.92'}


def test_line_amounts_rounded_half_up():
    out = invoice_total([_l(1, '2.345', False), _l(3, '0.3333', False)], '0.10')
    assert out == {'subtotal': '3.35', 'discount': '0.00', 'tax': '0.00', 'total': '3.35'}


def test_tax_rounded_once_on_the_sum():
    out = invoice_total([_l(1, '0.05', True), _l(1, '0.05', True)], '0.08')
    assert out == {'subtotal': '0.10', 'discount': '0.00', 'tax': '0.01', 'total': '0.11'}


def test_discount_split_across_all_lines():
    out = invoice_total([_l(1, '10.00', True), _l(1, '20.00', False)], '0.10', discount='10.00')
    assert out == {'subtotal': '30.00', 'discount': '10.00', 'tax': '0.67', 'total': '20.67'}


def test_discount_remainder_tie_goes_to_earlier_line():
    out = invoice_total([_l(1, '10.03', False), _l(1, '10.03', True)], '0.5', discount='0.01')
    assert out == {'subtotal': '20.06', 'discount': '0.01', 'tax': '5.02', 'total': '25.07'}


def test_discount_capped_at_subtotal():
    out = invoice_total([_l(1, '10.00', True), _l(2, '10.00', False)], '0.0825', discount='100')
    assert out == {'subtotal': '30.00', 'discount': '30.00', 'tax': '0.00', 'total': '0.00'}
    out = invoice_total([_l(0, '5.00', True)], '0.0825', discount='5')
    assert out == {'subtotal': '0.00', 'discount': '0.00', 'tax': '0.00', 'total': '0.00'}


def test_mixed_invoice_with_discount():
    lines = [_l(2, '12.5', True), _l(1, '7.25', True), _l(4, '0.99', False)]
    out = invoice_total(lines, '0.0725', discount='3.33')
    assert out == {'subtotal': '36.21', 'discount': '3.33', 'tax': '2.12', 'total': '35.00'}

