from datetime import date, timedelta


def _fy_start(year):
    feb1 = date(year, 2, 1)
    back = (feb1.weekday() + 1) % 7
    if back <= 3:
        return feb1 - timedelta(days=back)
    return feb1 + timedelta(days=7 - back)


def retail_period(date_str: str) -> str:
    d = date.fromisoformat(date_str)
    year = d.year if d >= _fy_start(d.year) else d.year - 1
    week = (d - _fy_start(year)).days // 7 + 1
    q = min((week - 1) // 13, 3)
    wq = week - 1 - 13 * q
    p_in_q = 0 if wq < 4 else (1 if wq < 8 else 2)
    period = 3 * q + p_in_q + 1
    return f"FY{year}-Q{q + 1}-P{period:02d}-W{week:02d}"

import calendar
import re
from datetime import date, timedelta

_ORD = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "last": -1}
_WD = {name.lower(): i for i, name in enumerate(calendar.day_name)}


def _occurrence(y, m, n, wd):
    if n > 0:
        first = date(y, m, 1)
        d = first + timedelta(days=(wd - first.weekday()) % 7 + 7 * (n - 1))
        return d if d.month == m else None
    last = date(y, m, calendar.monthrange(y, m)[1])
    return last - timedelta(days=(last.weekday() - wd) % 7)


def meeting_dates(rule: str, start: str, end: str, holidays: list = None) -> list:
    m = re.fullmatch(r"([A-Za-z]+) ([A-Za-z]+)(?: ([+-])(\d+))?", rule)
    if not m or m.group(1).lower() not in _ORD or m.group(2).lower() not in _WD:
        raise ValueError(f"bad rule: {rule!r}")
    n, wd = _ORD[m.group(1).lower()], _WD[m.group(2).lower()]
    offset = 0 if m.group(3) is None else int(m.group(4)) * (1 if m.group(3) == "+" else -1)
    hol = {date.fromisoformat(h) for h in (holidays or [])}
    s, e = date.fromisoformat(start), date.fromisoformat(end)
    margin = timedelta(days=abs(offset) + 2 * len(hol) + 40)
    lo, hi = s - margin, e + margin
    y, mo = lo.year, lo.month
    out = []
    while (y, mo) <= (hi.year, hi.month):
        d = _occurrence(y, mo, n, wd)
        if d is not None:
            d += timedelta(days=offset)
            if d in hol:
                d -= timedelta(days=1)
                while d.weekday() >= 5 or d in hol:
                    d -= timedelta(days=1)
            if s <= d <= e:
                out.append(d.isoformat())
        y, mo = (y + 1, 1) if mo == 12 else (y, mo + 1)
    return sorted(set(out))

