P = ['ann', 'bob', 'cat']


def test_even_split_leftover_in_people_order():
    assert split_bill([(1000, [])], P, '0', '0') == {'ann': 334, 'bob': 333, 'cat': 333}
    assert split_bill([(100, ['cat', 'bob', 'ann'])], P, '0', '0') == {'ann': 34, 'bob': 33, 'cat': 33}


def test_bill_level_tax_split_by_largest_remainder():
    assert split_bill([(1000, [])], P, '0.0825', '0') == {'ann': 362, 'bob': 361, 'cat': 360}
    assert split_bill([(1001, ['ann', 'cat'])], P, '0.0825', '0.15') == {'ann': 618, 'bob': 0, 'cat': 616}


def test_tip_on_pre_tax_amount():
    assert split_bill([(1500, ['bob'])], P, '0.1', '0.15') == {'ann': 0, 'bob': 1875, 'cat': 0}
    assert split_bill([(1000, [])], P, '0.0825', '0.18') == {'ann': 422, 'bob': 421, 'cat': 420}


def test_tax_and_tip_split_separately():
    items = [(2400, ['ann', 'bob']), (1250, ['cat']), (999, [])]
    out = split_bill(items, P, '0.07', '0.2')
    assert out == {'ann': 1947, 'bob': 1946, 'cat': 2011}
    assert sum(out.values()) == 4649 + 325 + 930


def test_no_items():
    assert split_bill([], P, '0.1', '0.2') == {'ann': 0, 'bob': 0, 'cat': 0}


def test_exempt_guest():
    assert split_bill([(1000, []), (500, ['cat'])], P, '0.0825', '0.18', exempt=['cat']) == {
        'ann': 948, 'bob': 946, 'cat': 0}
    assert split_bill([(3001, ['cat']), (1000, ['ann', 'bob'])], P, '0.0825', '0.18', exempt=['cat']) == {
        'ann': 2526, 'bob': 2525, 'cat': 0}


def test_several_exempt_guests():
    items = [(1234, ['ann']), (4321, ['bob']), (777, ['cat']), (55, ['dan'])]
    out = split_bill(items, P + ['dan'], '0.0875', '0.2', exempt=['bob', 'dan'])
    assert out == {'ann': 4407, 'bob': 0, 'cat': 3816, 'dan': 0}

