from decimal import Decimal, ROUND_HALF_UP


def _proportional(total, weights):
    W = sum(weights)
    if total == 0 or W == 0:
        return [0] * len(weights)
    shares = [total * w // W for w in weights]
    rems = [total * w % W for w in weights]
    left = total - sum(shares)
    for i in sorted(range(len(weights)), key=lambda i: (-rems[i], i))[:left]:
        shares[i] += 1
    return shares


def _even(amount, idxs, out):
    q, r = divmod(amount, len(idxs))
    for j, i in enumerate(sorted(idxs)):
        out[i] += q + (1 if j < r else 0)


def split_bill(items: list, people: list, tax_rate: str, tip_rate: str, exempt: list = None) -> dict:
    pos = {p: i for i, p in enumerate(people)}
    sub = [0] * len(people)
    for price, sharers in items:
        idxs = [pos[p] for p in sharers] if sharers else list(range(len(people)))
        _even(price, idxs, sub)
    total_sub = sum(sub)
    ex = set(exempt or [])
    payers = [i for i, p in enumerate(people) if p not in ex]
    adj = [0 if p in ex else sub[i] for i, p in enumerate(people)]
    for i, p in enumerate(people):
        if p in ex and sub[i]:
            _even(sub[i], payers, adj)

    def bill(rate):
        return int((total_sub * Decimal(rate)).quantize(Decimal(1), rounding=ROUND_HALF_UP))

    tax = _proportional(bill(tax_rate), adj)
    tip = _proportional(bill(tip_rate), adj)
    return {p: adj[i] + tax[i] + tip[i] for i, p in enumerate(people)}

